--
-- TOC entry 308 (class 1259 OID 25942)
-- Name: aeade_ventas_acumulado_mensual; Type: VIEW; Schema: spo; Owner: postgres
--

CREATE VIEW spo.aeade_ventas_acumulado_mensual AS
 SELECT marca,
    (EXTRACT(year FROM fecha))::integer AS anio,
    (EXTRACT(month FROM fecha))::integer AS mes,
    sum(ventas) AS unidades
   FROM spo.aeade_ventas_normalizado
  WHERE (tipo = 'acumulado'::text)
  GROUP BY marca, (EXTRACT(year FROM fecha)), (EXTRACT(month FROM fecha))
  ORDER BY marca, ((EXTRACT(year FROM fecha))::integer), ((EXTRACT(month FROM fecha))::integer);


ALTER VIEW spo.aeade_ventas_acumulado_mensual OWNER TO postgres;

